-- Keep the casting notes on the existing production character record.
ALTER TABLE public.production_characters
  ADD COLUMN IF NOT EXISTS written_as text,
  ADD COLUMN IF NOT EXISTS casting_eligibility text NOT NULL DEFAULT 'unspecified',
  ADD COLUMN IF NOT EXISTS casting_notes text,
  ADD COLUMN IF NOT EXISTS performance_disciplines text[] NOT NULL DEFAULT '{}';

ALTER TABLE public.production_characters
  DROP CONSTRAINT IF EXISTS production_characters_casting_eligibility_check;
ALTER TABLE public.production_characters
  ADD CONSTRAINT production_characters_casting_eligibility_check
  CHECK (casting_eligibility IN ('open', 'character_gender', 'specific', 'unspecified'));

CREATE OR REPLACE VIEW public.bts_visible_characters WITH(security_barrier=true) AS SELECT c.id,c.production_id,c.name,c.performer_count,c.sort_order,c.show_on_form,c.show_on_public_page,c.vocal_type,c.vocal_range,c.vocal_usage,c.role_type,c.gender,c.age_range,c.description,c.singing_strength,c.dancing_strength,c.beginner_friendly,c.audition_material,c.created_at,c.audition_file_url,c.audition_file_path,c.audition_file_name,c.audition_side_url,c.audition_side_path,c.audition_side_name,c.audition_songcut_url,c.audition_songcut_path,c.audition_songcut_name,c.audition_other_url,c.audition_other_path,c.audition_other_name,c.audition_side_notes,c.audition_songcut_notes,c.audition_other_notes,c.audition_material_types,c.dance_call_file_url,c.other_file_url,c.dance_call_file_path,c.other_file_path,c.dance_call_file_name,c.other_file_name,c.dance_call_material_types,c.other_material_types,c.dance_call_side_url,c.dance_call_side_path,c.dance_call_side_name,c.dance_call_songcut_url,c.dance_call_songcut_path,c.dance_call_songcut_name,c.dance_call_other_url,c.dance_call_other_path,c.dance_call_other_name,c.other_side_url,c.other_side_path,c.other_side_name,c.other_songcut_url,c.other_songcut_path,c.other_songcut_name,c.other_other_url,c.other_other_path,c.other_other_name,c.dance_call_side_notes,c.dance_call_songcut_notes,c.dance_call_other_notes,c.other_side_notes,c.other_songcut_notes,c.other_other_notes,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_material END AS callback_material,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_file_url END AS callback_file_url,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_file_path END AS callback_file_path,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_file_name END AS callback_file_name,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_side_url END AS callback_side_url,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_side_path END AS callback_side_path,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_side_name END AS callback_side_name,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_songcut_url END AS callback_songcut_url,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_songcut_path END AS callback_songcut_path,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_songcut_name END AS callback_songcut_name,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_other_url END AS callback_other_url,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_other_path END AS callback_other_path,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_other_name END AS callback_other_name,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_side_notes END AS callback_side_notes,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_songcut_notes END AS callback_songcut_notes,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_other_notes END AS callback_other_notes,CASE WHEN public.bts_callback_access(c.production_id) THEN c.callback_material_types END AS callback_material_types,c.written_as,c.casting_eligibility,CASE WHEN c.casting_eligibility='specific' THEN c.casting_notes END AS casting_notes,c.performance_disciplines FROM public.production_characters c WHERE public.bts_production_page_permission(c.production_id,'auditions.general',1) OR public.bts_is_production_participant(c.production_id) OR (c.show_on_public_page AND EXISTS(SELECT 1 FROM public.productions p WHERE p.id=c.production_id AND p.is_public AND p.page_status IN ('live','hidden')));
